const body = $('Webhook').first().json.body || {};
const zoneId = (body['Cloudflare Zone ID'] || '').trim();
const token = (body['Cloudflare Token'] || '').trim();

if (!zoneId || !token) {
  throw new Error('Cloudflare Zone ID ou Token não foram fornecidos.');
}

const PER_PAGE = 100;
let page = 1;
let totalPages = 1;
const allRecords = [];

do {
  let response;
  try {
    response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.cloudflare.com/client/v4/zones/${zoneId}/dns_records?per_page=${PER_PAGE}&page=${page}`,
      headers: { Authorization: `Bearer ${token}` },
      json: true,
    });
  } catch (error) {
    const status = error.httpCode || error.response?.status || error.statusCode;
    if (String(status) === '403' || String(status) === '401') {
      throw new Error("Cloudflare recusou o token: inválido, expirado ou sem a permissão 'Zone.DNS:Read'.");
    }
    throw error;
  }

  allRecords.push(...(response?.result || []));
  totalPages = response?.result_info?.total_pages || 1;
  page++;
} while (page <= totalPages);

return [{ json: { result: allRecords } }];

// Agrupa os registros proxied (nuvem laranja) por destino (IP ou CNAME).
// Cada destino vira um "site": 1 Connector + 1 Application + 1 Workload.
const records = $input.first().json.result || [];
const PROXIABLE = ['A', 'AAAA', 'CNAME'];
const grouped = {};

for (const record of records) {
  if (record.proxied !== true || !PROXIABLE.includes(record.type)) continue;
  const content = record.content;
  if (!grouped[content]) grouped[content] = new Set();
  grouped[content].add(record.name);
}

const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// Os nomes são determinísticos: é o que permite reaproveitar os recursos numa nova execução.
const groups = Object.entries(grouped).map(([content, names]) => {
  const domains = [...names].sort();
  return {
    target_content: content,
    domains,
    connector_name: `conn-${slug(content)}`.slice(0, 100),
    application_name: `app-${slug(content)}`.slice(0, 100),
    workload_name: `workload-${slug(domains[0])}`.slice(0, 100),
  };
});

// Sempre devolve 1 item, mesmo sem registros proxied, para o relatório/resposta rodarem.
return [{ json: { total_records: records.length, groups } }];

// Provisiona cada grupo na Azion de forma idempotente:
// procura pelo nome antes de criar e só altera o que estiver diferente.
const body = $('Webhook').first().json.body || {};
const azToken = (body['Azion Token'] || '').trim();
const baseAppId = String(body['Azion Base Edge App ID (Origin)'] || '').trim();
const { groups } = $input.first().json;
const helpers = this.helpers;

if (!azToken || !baseAppId) {
  throw new Error('Azion Token ou Base Edge App ID não foram fornecidos.');
}

const AZ = 'https://api.azion.com/v4';
const CONNECTOR_BEHAVIORS = ['set_connector', 'set_origin'];

async function az(method, path, payload) {
  try {
    return await helpers.httpRequest({
      method,
      url: `${AZ}${path}`,
      headers: {
        Accept: 'application/json',
        Authorization: `TOKEN ${azToken}`,
        'Content-Type': 'application/json',
      },
      body: payload,
      json: true,
    });
  } catch (e) {
    const status = e.httpCode || e.response?.status || e.statusCode || '';
    const detail = e.response?.body ?? e.description ?? e.message;
    throw new Error(`${method} ${path} → ${status} ${typeof detail === 'string' ? detail : JSON.stringify(detail)}`);
  }
}

async function findByName(path, name) {
  const res = await az('GET', `${path}?name=${encodeURIComponent(name)}&page_size=100`);
  return (res?.results || []).find((r) => r.name === name) || null;
}

const idOf = (res) => res?.data?.id ?? res?.id;

async function ensureConnector(g) {
  const found = await findByName('/workspace/connectors', g.connector_name);
  if (found) return { id: found.id, status: 'reutilizado' };
  const res = await az('POST', '/workspace/connectors', {
    name: g.connector_name,
    active: true,
    type: 'http',
    attributes: {
      addresses: [{ active: true, address: g.target_content, http_port: 80, https_port: 443 }],
      connection_options: {
        dns_resolution: 'both',
        transport_policy: 'preserve',
        http_version_policy: 'http1_1',
        host: '${host}',
        path_prefix: '',
        following_redirect: false,
        real_ip_header: 'X-Real-IP',
        real_port_header: 'X-Real-PORT',
      },
    },
  });
  return { id: idOf(res), status: 'criado' };
}

async function ensureApplication(g) {
  const found = await findByName('/workspace/applications', g.application_name);
  if (found) return { id: found.id, status: 'reutilizado' };
  const res = await az('POST', `/workspace/applications/${baseAppId}/clone`, { name: g.application_name });
  return { id: idOf(res), status: 'criado' };
}

// Troca, nas regras de request da app clonada, todo set_connector/set_origin pelo connector do grupo.
async function pointRulesToConnector(appId, connectorId) {
  const res = await az('GET', `/workspace/applications/${appId}/request_rules?page_size=100`);
  const rules = res?.results || [];
  const withConnector = rules.filter((r) => (r.behaviors || []).some((b) => CONNECTOR_BEHAVIORS.includes(b.type)));

  if (withConnector.length === 0) {
    // A app modelo não define connector em nenhuma regra: adiciona na regra padrão (primeira).
    const def = rules[0];
    if (!def) throw new Error('A Application modelo não tem regras de request.');
    await az('PATCH', `/workspace/applications/${appId}/request_rules/${def.id}`, {
      behaviors: [...def.behaviors, { type: 'set_connector', attributes: { value: connectorId } }],
    });
    return 'atualizado';
  }

  let changed = false;
  for (const rule of withConnector) {
    const alreadyOk = rule.behaviors.every(
      (b) => !CONNECTOR_BEHAVIORS.includes(b.type) || (b.type === 'set_connector' && b.attributes?.value === connectorId),
    );
    if (alreadyOk) continue;
    const behaviors = rule.behaviors.map((b) =>
      CONNECTOR_BEHAVIORS.includes(b.type) ? { type: 'set_connector', attributes: { value: connectorId } } : b,
    );
    await az('PATCH', `/workspace/applications/${appId}/request_rules/${rule.id}`, { behaviors });
    changed = true;
  }
  return changed ? 'atualizado' : 'reutilizado';
}

async function ensureWorkload(g) {
  const found = await findByName('/workspace/workloads', g.workload_name);
  if (found) {
    const current = [...(found.domains || [])].sort();
    if (JSON.stringify(current) === JSON.stringify(g.domains)) return { id: found.id, status: 'reutilizado' };
    await az('PATCH', `/workspace/workloads/${found.id}`, { domains: g.domains });
    return { id: found.id, status: 'atualizado' };
  }
  // Sem certificado por enquanto: emissão de TLS fica para um segundo step.
  const res = await az('POST', '/workspace/workloads', {
    name: g.workload_name,
    active: true,
    infrastructure: 1,
    protocols: {
      http: { versions: ['http1', 'http2'], http_ports: [80], https_ports: [443], quic_ports: [] },
    },
    domains: g.domains,
    workload_domain_allow_access: true,
  });
  return { id: idOf(res), status: 'criado' };
}

// O vínculo Workload → Application é feito por um deployment, não no corpo do workload.
async function ensureDeployment(workloadId, appId, appName) {
  const res = await az('GET', `/workspace/workloads/${workloadId}/deployments`);
  const deployments = res?.results || [];
  const strategy = { type: 'default', attributes: { application: appId } };

  if (deployments.some((d) => d.strategy?.attributes?.application === appId)) return 'reutilizado';

  if (deployments.length > 0) {
    await az('PATCH', `/workspace/workloads/${workloadId}/deployments/${deployments[0].id}`, { strategy });
    return 'atualizado';
  }

  await az('POST', `/workspace/workloads/${workloadId}/deployments`, {
    name: `deploy-${appName}`.slice(0, 100),
    active: true,
    current: true,
    strategy,
  });
  return 'criado';
}

const results = [];

for (const g of groups) {
  const r = { ...g, connector: null, application: null, rules: null, workload: null, deployment: null, error: null };
  try {
    r.connector = await ensureConnector(g);
    r.application = await ensureApplication(g);
    r.rules = await pointRulesToConnector(r.application.id, r.connector.id);
    r.workload = await ensureWorkload(g);
    r.deployment = await ensureDeployment(r.workload.id, r.application.id, g.application_name);
  } catch (e) {
    // Um grupo com erro não interrompe os demais.
    r.error = e.message;
  }
  results.push(r);
}

return [{ json: { results } }];

// Relatório simples em HTML. O mesmo `results` pode alimentar um nó de e-mail ou Slack depois.
const { results } = $input.first().json;
const { total_records } = $('Filter Proxied & Group').first().json;

const esc = (s) => String(s ?? '-').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const COLORS = { criado: '#28a745', atualizado: '#0056b3', reutilizado: '#6c757d' };
const cell = (name, step) => {
  if (!step) return '<td><span style="color:#999">—</span></td>';
  const status = typeof step === 'string' ? step : step.status;
  const id = typeof step === 'object' && step.id ? ` <small>#${esc(step.id)}</small>` : '';
  return `<td>${name ? `<code>${esc(name)}</code>${id}<br>` : ''}<span style="color:${COLORS[status] || '#333'};font-weight:bold">${esc(status)}</span></td>`;
};

const ok = results.filter((r) => !r.error).length;
const failed = results.length - ok;

const rows = results
  .map(
    (r) => `
    <tr>
      <td>${r.domains.map(esc).join('<br>')}</td>
      <td><code>${esc(r.target_content)}</code></td>
      ${cell(r.connector_name, r.connector)}
      ${cell(r.application_name, r.application)}
      ${cell(null, r.rules)}
      ${cell(r.workload_name, r.workload)}
      ${cell(null, r.deployment)}
      <td>${r.error ? `<span style="color:#dc3545;font-weight:bold">✖ Erro</span><br><small>${esc(r.error)}</small>` : '<span style="color:#28a745;font-weight:bold">✔ OK</span>'}</td>
    </tr>`,
  )
  .join('');

const htmlContent = `
<style>
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background-color: #f4f6f8; color: #333; }
  .report-wrapper { max-width: 1200px; margin: auto; background: white; padding: 20px; border-radius: 8px; }
  h2 { color: #0056b3; font-size: 20px; margin-bottom: 5px; }
  .subtitle { color: #666; font-size: 13px; margin-bottom: 15px; border-bottom: 1px solid #eee; padding-bottom: 8px; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th, td { border: 1px solid #e1e4e8; padding: 10px; text-align: left; font-size: 13px; vertical-align: top; }
  th { background-color: #f8f9fa; color: #495057; font-weight: 600; }
  tr:nth-child(even) { background-color: #fcfcfc; }
  code { background: #eef1f6; padding: 3px 6px; border-radius: 4px; font-family: monospace; color: #0056b3; font-size: 12px; }
  small { color: #666; word-break: break-word; }
  .actions { margin-top: 20px; text-align: right; }
  .btn { background: #0056b3; color: white; border: none; padding: 8px 16px; border-radius: 6px; cursor: pointer; font-size: 13px; font-weight: bold; }
  @media print { .actions { display: none; } }
</style>

<div class="report-wrapper">
  <h2>Relatório de Provisionamento - Azion</h2>
  <div class="subtitle">
    Gerado em: ${new Date().toLocaleString('pt-BR')} ·
    ${total_records} registros DNS lidos · ${results.length} origens proxied ·
    ${ok} OK · ${failed} com erro
  </div>
  ${
    results.length === 0
      ? '<p>Nenhum registro proxied (nuvem laranja) encontrado na zona. Nada foi criado.</p>'
      : `<table>
    <thead>
      <tr>
        <th>Domínio(s)</th><th>Origem</th><th>Connector</th><th>Application</th>
        <th>Regras → Connector</th><th>Workload</th><th>Deployment</th><th>Status</th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>`
  }
  <div class="actions">
    <button class="btn" onclick="window.print()">📄 Exportar / Salvar como PDF</button>
  </div>
</div>
`;

return [{ json: { htmlContent, summary: { total_records, groups: results.length, ok, failed }, results } }];
